	template <typename T> inline T* Cast(Instance* inst)
	{
		return inst ? T::FromDebugId(inst->GetDebugId()) : nullptr;
	}
	template <typename T> inline T* GetService()
	{
		auto* raw = Instance::GetInstance(
			std::string("game:GetService(\"") + T::RBXClassName + "\")");
		if (!raw) return nullptr;
		auto* typed = T::FromDebugId(raw->GetDebugId());
		delete raw;
		return typed;
	}

	// Typed factory: `auto* p = RBX::New<RBX::Part>(workspace);` returns a
	// strongly-typed Part*, equivalent to `new RBX::Part(workspace)` but
	// reads more naturally next to RBX::Cast<T> / RBX::GetService<T>.
	template <typename T, typename... Args>
	inline T* New(Args&&... args)
	{
		return new T(std::forward<Args>(args)...);
	}

